import assert from 'node:assert/strict';
import test from 'node:test';

import { lateOwnedSheets, readSheetShares } from '../lib/css-sheet-shares.mjs';

const bundle = [
  '/* Generated by scripts/css-bundle.mjs — do not edit by hand. */',
  '/* /public/css/reset/base.css */',
  '@layer reset {',
  '  html { margin: 0; }',
  '}',
  '/* /public/css/systems/expression-resonance.css */',
  '@layer systems {',
  '  /* ── a banner that is not a provenance line ── */',
  '  .a::before { content: "é"; }',
  '}',
  '/* /public/css/systems/spw-key-events.css */',
  '@layer systems { .b { color: red; } }',
  '',
].join('\n');

test('sheets, provenance lines and the header add up to the bundle exactly', () => {
  const shares = readSheetShares(bundle);
  assert.equal(shares.sheets.length, 3);
  assert.equal(shares.sheetBytes + shares.provenanceBytes + shares.headerBytes, shares.totalBytes);
  assert.equal(shares.balanced, true);
  assert.equal(shares.totalBytes, Buffer.byteLength(bundle, 'utf8'), 'bytes, not characters: the é counts twice');
});

test('sheets fold by the layer folder they live in, heaviest folder first', () => {
  const shares = readSheetShares(bundle);
  assert.deepEqual(shares.folders.map((row) => [row.folder, row.sheets]), [['systems', 2], ['reset', 1]]);
  assert.equal(shares.folders[0].bytes, shares.sheets[1].bytes + shares.sheets[2].bytes);
});

test('a sheet that shares a module id carries that module\'s mount timing', () => {
  const when = { 'expression-resonance': 'idle', 'spw-key-events': 'immediate' };
  const shares = readSheetShares(bundle, { whenOf: (id) => when[id] });
  assert.equal(shares.sheets[0].when, undefined, 'no module is named base');
  assert.deepEqual(lateOwnedSheets(shares).map((sheet) => [sheet.name, sheet.when]), [['expression-resonance', 'idle']]);
});
